<#
  NUDGE Figma variables: generator.

  Reads the SOURCE specifications in this folder (collections.source.json, primitives.json, spacing.json, typography.json,
  semantic.json, layout.json, component-variables.json) and WRITES the GENERATED outputs:
    variable-map.json         the consolidated variable map (all collections, modes, values, aliases, resolved values, styles)
    collections.md            human-readable collections, modes and variable tables
    mapping-report.md         every one of the 333 web tokens classified: shared, mapped differently, or not a variable (with the Figma alternative)
    apply-variables.figma.js  a Figma Plugin API script that would create the collections and variables. NOT EXECUTED: see README.md

  It reads the web tokens (../Tokens) READ-ONLY. It never writes outside 02-Design-Variables/Figma-Variables/.
  Run:  powershell -ExecutionPolicy Bypass -File 02-Design-Variables/Figma-Variables/build-figma-variables.ps1
  Exit code 0 = written, 1 = a source problem (message names the variable).
#>
$ErrorActionPreference = 'Stop'
$here = $PSScriptRoot
$proj = Split-Path -Parent (Split-Path -Parent $here)   # project root
. (Join-Path $here 'figma-tools.ps1')
$enc = New-Object Text.UTF8Encoding($false)
$nl = "`n"
$spec = Load-FigmaSpec $here
$webDir = Join-Path $proj '02-Design-Variables\Tokens'
$webList = Get-WebTokens $webDir
$web = @{}; foreach ($w in $webList) { $web[$w.path] = $w }

# ---------- 1. resolve every variable in every mode ----------
$collByName = @{}; foreach ($c in $spec.collections) { $collByName[$c.name] = $c }
$webByCss = @{}; foreach ($w0 in $webList) { $webByCss[$w0.css] = $w0 }
$webScope = Get-WebScope $webDir
$tierKey = @{ Mobile = 'mobile'; Tablet = 'tablet'; Desktop = 'desktop'; Value = 'mobile'; Default = 'mobile'; Inverse = 'mobile' }
$mapVars = @()
foreach ($v in $spec.variables) {
  if (-not $collByName.ContainsKey($v.collection)) { throw "Variable $($v.name) uses unknown collection '$($v.collection)'" }
  $c = $collByName[$v.collection]
  $webRaw = $null; $webRes = [ordered]@{}
  if ($v.webToken -and $webByCss.ContainsKey($v.webToken)) {
    $wt = $webByCss[$v.webToken]
    $webRaw = if ($wt.raw -is [pscustomobject]) { $o = [ordered]@{}; foreach ($pp in $wt.raw.PSObject.Properties) { $o[$pp.Name] = [string]$pp.Value }; $o } else { [string]$wt.raw }
    foreach ($m0 in $c.modes) { $ov = if ($m0 -eq 'Inverse') { $webScope } else { $null }; $wd = if ($script:RefWidths.ContainsKey($m0)) { $script:RefWidths[$m0] } else { 0 }; $rv = Resolve-Web $web $wt.path $tierKey[$m0] $ov $wd; if ($rv -is [double] -or $rv -is [int] -or $rv -is [decimal]) { $rv = [math]::Round([double]$rv, 3) }; $webRes[$m0] = $rv }
  }
  $vals = [ordered]@{}
  foreach ($m in $c.modes) {
    $raw = (ValuesOf $v)[$m]
    if ($null -eq $raw) { throw "Variable $($v.name) is missing a value for mode '$m' of $($c.name)" }
    $a = Get-AliasName $raw
    $vals[$m] = [ordered]@{ kind = $(if ($a) { 'alias' } else { 'literal' }); raw = $raw; alias = $a; resolved = (Resolve-Figma $spec $v $m) }
  }
  $mapVars += [ordered]@{ id = $v.name; name = $v.name; collection = $v.collection; type = $v.type; layer = $v.layer; description = $v.description; scopes = @($v.scopes); hiddenFromPublishing = [bool]$v.hiddenFromPublishing; webToken = [string]$v.webToken; webRelation = [string]$v.webRelation; webRaw = $webRaw; webResolved = $webRes; sourceFile = $v.sourceFile; values = $vals }
}
$modeOf = @{}; foreach ($c in $spec.collections) { $modeOf[$c.name] = @($c.modes) }

# ---------- 2. text styles resolved ----------
$styles = @()
foreach ($s in $spec.textStyles) {
  $fam = Resolve-Figma $spec $spec.byName[(Get-AliasName $s.fontFamily)] 'Value'
  $wt = Resolve-Figma $spec $spec.byName[(Get-AliasName $s.fontWeight)] 'Value'
  $sz = [ordered]@{}; foreach ($m in 'Mobile', 'Tablet', 'Desktop') { $sz[$m] = Resolve-Figma $spec $spec.byName[(Get-AliasName $s.fontSize)] $m }
  $styles += [ordered]@{ name = $s.name; webRole = $s.webRole; fontFamilyVariable = (Get-AliasName $s.fontFamily); fontFamily = $fam; fontWeightVariable = (Get-AliasName $s.fontWeight); fontWeight = $wt; fontSizeVariable = (Get-AliasName $s.fontSize); fontSizePx = $sz; lineHeightPercent = $s.lineHeightPercent; letterSpacingPercent = $s.letterSpacingPercent; textCase = $s.textCase; usage = $s.usage }
}
$counts = [ordered]@{ collections = $spec.collections.Count; variables = $mapVars.Count; textStyles = $styles.Count; gridStyles = @($spec.gridStyles).Count; effectStyles = @($spec.effectStyles).Count }
foreach ($c in $spec.collections) { $counts["variables in $($c.name)"] = @($mapVars | Where-Object { $_.collection -eq $c.name }).Count }
$map = [ordered]@{
  meta = [ordered]@{ kind = 'generated'; note = 'GENERATED by build-figma-variables.ps1 from the source specifications. DO NOT EDIT BY HAND. This is a specification file: it is NOT a Figma file and nothing here was created in Figma.'; specVersion = '1.0'; sources = @('collections.source.json') + $script:SourceFiles; counts = $counts }
  collections = @($spec.collections | ForEach-Object { [ordered]@{ name = $_.name; modes = @($_.modes); defaultMode = $_.defaultMode; purpose = $_.purpose; modeRationale = $_.modeRationale; variableCount = @($mapVars | Where-Object { $_.collection -eq $_.name }).Count } })
  variables = $mapVars
  textStyles = $styles
  gridStyles = @($spec.gridStyles)
  effectStyles = @($spec.effectStyles)
}
foreach ($c in $map.collections) { $n = $c.name; $c.variableCount = @($mapVars | Where-Object { $_.collection -eq $n }).Count }


# ---------- 3. collections.md ----------
function Fmt($r) { if ($r.kind -eq 'alias') { "``{$($r.alias)}`` = $($r.resolved)" } else { "$($r.resolved)" } }
$m = New-Object Text.StringBuilder
[void]$m.Append("<!-- GENERATED by build-figma-variables.ps1 from the source specifications. DO NOT EDIT BY HAND. -->$nl# Figma Variables: collections, modes and variables$nl$nl")
[void]$m.Append("This is a **specification** for Figma Variables. Nothing here was created in Figma (see [README.md](README.md)). Counts: $($counts.collections) collections, $($counts.variables) variables, $($counts.textStyles) text styles, $($counts.gridStyles) grid styles, $($counts.effectStyles) effect styles.$nl$nl")
[void]$m.Append("| Collection | Modes | Variables | Purpose |$nl|---|---|---|---|$nl")
foreach ($c in $map.collections) { [void]$m.Append("| **$($c.name)** | $(($c.modes) -join ', ') | $($c.variableCount) | $($c.purpose) |$nl") }
[void]$m.Append("$nl## Mode decisions$nl$nl| Candidate | Decision | Reason |$nl|---|---|---|$nl")
foreach ($d in $spec.modeDecisions) { [void]$m.Append("| $($d.candidate) | $($d.decision) | $($d.reason) |$nl") }
[void]$m.Append("$nl## How mode switching works$nl$nl- Select a frame, open the Layers panel's appearance section (or the Variables mode picker), and set the **collection's mode** on that frame. Every child inherits it unless it sets its own.$nl- **Semantic: Inverse** on a footer or promotional frame re-resolves every bound colour inside it, including variables that alias other semantic variables (for example the secondary button border follows text/primary).$nl- **Layout and Typography: Mobile, Tablet, Desktop** on a page frame re-resolves gutters, gaps, section spacing, header height and font sizes together. Set both collections to the same tier on a page frame. The three modes are discrete samples: the web system is continuous between them.$nl- Values that are **not suited to modes**: shadows, line height and letter spacing, motion, z-order, aspect ratios, grid column counts and the drawer sheet width (see [mapping-report.md](mapping-report.md)).$nl")
foreach ($c in $map.collections) {
  [void]$m.Append("$nl## $($c.name)$nl$nl**Modes:** $(($c.modes) -join ', ') (default: $($c.defaultMode)). $($c.modeRationale)$nl$nl")
  $hdr = "| Variable | Type | Layer |"; $sep = "|---|---|---|"
  foreach ($md in $c.modes) { $hdr += " $md |"; $sep += "---|" }
  $hdr += " Web token | Relation | Intended use |"; $sep += "---|---|---|"
  [void]$m.Append("$hdr$nl$sep$nl")
  foreach ($v in ($mapVars | Where-Object { $_.collection -eq $c.name })) {
    $row = "| ``$($v.name)`` | $($v.type) | $($v.layer) |"
    foreach ($md in $c.modes) { $row += " $(Fmt $v.values[$md]) |" }
    $wt = if ($v.webToken) { "``$($v.webToken)``" } else { '(none)' }
    $row += " $wt | $($v.webRelation) | $($v.description) |"
    [void]$m.Append("$row$nl")
  }
}
[void]$m.Append("$nl## Text Styles, Grid Styles and Effect Styles (not Variables)$nl$nl")
[void]$m.Append("See [../../01-Design-System/Figma-Specification/typography-styles.md](../../01-Design-System/Figma-Specification/typography-styles.md) for the $($styles.Count) Text Styles. Grid Styles: $((@($spec.gridStyles) | ForEach-Object { $_.name }) -join ', '). Effect Styles: $((@($spec.effectStyles) | ForEach-Object { $_.name }) -join ', ').$nl")
[IO.File]::WriteAllText((Join-Path $here 'collections.md'), $m.ToString(), $enc)

# ---------- 4. mapping-report.md (all web tokens) ----------
$byWeb = @{}; foreach ($v in $mapVars) { if ($v.webToken) { $byWeb[$v.webToken] = $v } }
$rules = @(
  @('^--z-', 'Not a variable', 'Layer order is the layer stack in Figma; there is no z-index property.', 'Order layers in the frame.'),
  @('^--(duration|ease|transition)-', 'Not a variable', 'Interaction timing belongs to prototype transitions, which cannot bind to variables.', 'Set the duration and easing on each prototype interaction (Smart Animate, 200ms ease-out for most states).'),
  @('^--shadow-color$', 'Not a variable', 'The shadow colour is part of the Effect Styles.', 'Effect Styles bound to palette/charcoal.'),
  @('^--shadow-(sm|md|lg)$', 'Not a variable', 'A shadow is a bundle of offsets, blur and colour; a Variable cannot hold it.', 'Effect Styles Elevation/Small, Medium, Large.'),
  @('^--type-', 'Not a variable', 'Composite typography roles are Text Styles, which bundle family, weight, size, line height, letter spacing and case.', 'The 21 Text Styles (typography-styles.md); family, weight and size bind to variables.'),
  @('^--line-height-', 'Not a variable', 'Web line heights are unitless ratios. Figma line height is a percentage or pixel value stored in a Text Style.', 'lineHeightPercent in each Text Style (110, 125, 150, 165).'),
  @('^--letter-spacing-', 'Not a variable', 'Web letter spacing is in em. Figma stores letter spacing in a Text Style as a percentage or px.', 'letterSpacingPercent in each Text Style (em x 100).'),
  @('^--(aspect-|product-image-aspect-)', 'Not a variable', 'An aspect ratio is a frame property (lock proportions) or a sizing rule, not a number variable.', 'Use 4:5 (provisional), 1:1, 3:2, 3:4, 16:9 frames and lock the aspect ratio.'),
  @('^--breakpoint-', 'Mapped differently', 'Figma has no media queries; breakpoints become frame widths.', 'Variable layout/frame-width per tier (360, 768, 1280) and the Layout modes.'),
  @('^--grid-columns-products$', 'Not a variable', 'A grid column count is a layout-grid property and cannot be bound to a variable.', 'Grid Styles Grid/Products Mobile, Tablet, Desktop (2, 3, 4 columns).'),
  @('^--product-image-(fit|position|background)$', 'Not a variable', 'Object-fit and position are the image fill mode and crop in Figma; background is a normal fill.', 'Image fill Fill mode with a per-image crop; placeholder fill bound to color/bg/subtle.'),
  @('^--product-card-hover-zoom$', 'Not a variable', 'Hover zoom is a prototype interaction.', 'Smart Animate to scale 103% on hover (pointer devices only).'),
  @('^--focus-ring$', 'Not a variable', 'A composite (width, style, colour).', 'Represented by focus/ring-width, focus/ring-offset and color/focus/ring on the ring layer.'),
  @('^--layout-drawer-width$', 'Mapped differently', 'Web value is 100% below 600px and 26rem from 600px; a number variable cannot express 100%.', 'layout/drawer-width: 416 for Tablet and Desktop; on Mobile the sheet is Fill container (the 360 value is reference-only).'),
  @('^--space-section$', 'Mapped differently', 'Fluid clamp(): Figma has no continuous interpolation.', 'layout/section-spacing sampled at 360, 768 and 1280px (48, 66, 92).')
)
$rows = @(); $stats = @{ shared = 0; mapped = 0; figmaonly = 0; notvar = 0; notpromoted = 0; unexpected = 0 }
foreach ($w in $webList) {
  $css = $w.css
  if ($byWeb.ContainsKey($css)) {
    $v = $byWeb[$css]
    $cat = if ($v.webRelation -eq 'shared') { 'Shared' } else { 'Mapped differently' }
    if ($v.webRelation -eq 'shared') { $stats.shared++ } else { $stats.mapped++ }
    $alt = "Figma variable ``$($v.name)`` ($($v.collection))"
    $why = if ($v.webRelation -eq 'shared') { 'Same value (compared by validate-figma-variables.ps1).' } else { $v.description }
    $rows += [pscustomobject]@{ css = $css; cat = $cat; why = $why; alt = $alt }
    continue
  }
  $hit = $null; foreach ($r in $rules) { if ($css -match $r[0]) { $hit = $r; break } }
  if ($hit) { $rows += [pscustomobject]@{ css = $css; cat = $hit[1]; why = $hit[2]; alt = $hit[3] }; if ($hit[1] -eq 'Not a variable') { $stats.notvar++ } else { $stats.mapped++ }; continue }
  if ($css -match '^--(palette|color)-') { $stats.unexpected++; $rows += [pscustomobject]@{ css = $css; cat = 'UNMAPPED (unexpected)'; why = 'A colour token has no Figma variable and no rule.'; alt = 'Add it to the source specifications.' }; continue }
  $stats.notpromoted++
  $rows += [pscustomobject]@{ css = $css; cat = 'Not promoted'; why = 'A property of one component or a derived value; making it a variable would add maintenance without sharing.'; alt = 'Kept as a property in components.json (value derived from the shared variables).' }
}
$figmaOnly = @($mapVars | Where-Object { $_.webRelation -eq 'figma-only' })
$map['webMapping'] = @($rows | ForEach-Object { [ordered]@{ css = $_.css; category = $_.cat; figma = $_.alt; why = $_.why } })
$map['mappingSummary'] = [ordered]@{ total = $rows.Count; categories = [ordered]@{}; figmaOnlyVariables = @($figmaOnly | ForEach-Object { $_.name }) }
foreach ($g0 in ($rows | Group-Object cat | Sort-Object Name)) { $map['mappingSummary'].categories[$g0.Name] = $g0.Count }
[IO.File]::WriteAllText((Join-Path $here 'variable-map.json'), (($map | ConvertTo-Json -Depth 14) + $nl), $enc)
$r = New-Object Text.StringBuilder
[void]$r.Append("<!-- GENERATED by build-figma-variables.ps1. DO NOT EDIT BY HAND. -->$nl# Mapping report: web tokens to Figma$nl$nl")
[void]$r.Append("Every one of the $($webList.Count) web tokens in ``02-Design-Variables/Tokens`` is classified. The web files were read, not modified.$nl$nl")
[void]$r.Append("| Category | Count | Meaning |$nl|---|---|---|$nl")
$grp = $rows | Group-Object cat
foreach ($g in $grp | Sort-Object Name) { $mean = switch ($g.Name) { 'Shared' { 'A Figma variable holds the same value (same type; rem converted to px).' } 'Mapped differently' { 'A Figma variable exists, but the web value cannot be represented one to one (fluid, percentage, alias to a literal, name change, rounding).' } 'Not a variable' { 'No suitable Variable type; a Figma-native alternative is specified (Styles, Grid Styles, frame properties, prototype settings).' } 'Not promoted' { 'Technically possible but not promoted: used by one component or derived.' } default { '' } }; [void]$r.Append("| $($g.Name) | $($g.Count) | $mean |$nl") }
[void]$r.Append("| Figma-only variables (no web token) | $($figmaOnly.Count) | $((($figmaOnly | ForEach-Object { '`' + $_.name + '`' }) -join ', ')) |$nl")
[void]$r.Append("$nl**Total web tokens classified: $($rows.Count)** (expected $($webList.Count)). Unexpected unmapped colour tokens: $($stats.unexpected).$nl")
[void]$r.Append("$nl## Requires manual Figma configuration$nl$nl- Create the collections, modes and variables (script or by hand); there is no import that this project has tested.$nl- Create the 21 Text Styles and bind family, weight and size to variables; set line height and letter spacing in the style.$nl- Create the 3 Effect Styles and 3 Grid Styles.$nl- Install or enable the fonts **Cormorant** (Medium, SemiBold) and **DM Sans** (Regular, Medium, SemiBold). The web system self-hosts Latin subsets; Figma uses its font library.$nl- Build the components from [../../01-Design-System/Figma-Specification/components.md](../../01-Design-System/Figma-Specification/components.md).$nl$nl## Per-token classification$nl$nl| Web token | Category | Figma representation | Why |$nl|---|---|---|---|$nl")
foreach ($x in $rows) { [void]$r.Append("| ``$($x.css)`` | $($x.cat) | $($x.alt) | $($x.why) |$nl") }
[IO.File]::WriteAllText((Join-Path $here 'mapping-report.md'), $r.ToString(), $enc)

# ---------- 5. apply-variables.figma.js (NOT EXECUTED) ----------
$data = [ordered]@{
  collections = @($spec.collections | ForEach-Object { [ordered]@{ name = $_.name; modes = @($_.modes) } })
  variables = @($mapVars | ForEach-Object { $vv = $_; [ordered]@{ n = $vv.name; c = $vv.collection; t = $vv.type; s = @($vv.scopes); h = $vv.hiddenFromPublishing; d = $vv.description; v = ([ordered]@{} | ForEach-Object { $o = $_; foreach ($k in $vv.values.Keys) { $e = $vv.values[$k]; $o[$k] = $(if ($e.kind -eq 'alias') { [ordered]@{ a = $e.alias } } else { [ordered]@{ l = $e.resolved } }) }; $o }) } })
}
$json = $data | ConvertTo-Json -Depth 10 -Compress
$js = @"
/* GENERATED by build-figma-variables.ps1. DO NOT EDIT BY HAND.
   NOT EXECUTED: this script has never been run in Figma. Review it, then run it only in a NEW, empty Figma design file
   (Plugins > Development > New plugin > run, or any Plugin API console). It creates $($counts.collections) collections and $($counts.variables) variables;
   it does not create Text Styles, Effect Styles, Grid Styles or components. Verify the Plugin API calls against the current
   documentation: createVariable and the variable scopes names are the parts most likely to differ between API versions. */
const DATA = $json;
const hexToRgba = (h) => { const x = h.replace('#', ''); return { r: parseInt(x.slice(0, 2), 16) / 255, g: parseInt(x.slice(2, 4), 16) / 255, b: parseInt(x.slice(4, 6), 16) / 255, a: x.length === 8 ? parseInt(x.slice(6, 8), 16) / 255 : 1 }; };
const colls = {};
for (const c of DATA.collections) {
  const col = figma.variables.createVariableCollection(c.name);
  col.renameMode(col.modes[0].modeId, c.modes[0]);
  for (let i = 1; i < c.modes.length; i++) col.addMode(c.modes[i]);
  const ids = {}; col.modes.forEach((m) => { ids[m.name] = m.modeId; });
  colls[c.name] = { col, ids };
}
const created = {};
for (const v of DATA.variables) {
  const x = figma.variables.createVariable(v.n, colls[v.c].col, v.t);
  x.description = v.d; x.scopes = v.s; x.hiddenFromPublishing = v.h; created[v.n] = x;
}
for (const v of DATA.variables) {
  for (const mode of Object.keys(v.v)) {
    const val = v.v[mode]; const id = colls[v.c].ids[mode];
    if (val.a) created[v.n].setValueForMode(id, figma.variables.createVariableAlias(created[val.a]));
    else created[v.n].setValueForMode(id, v.t === 'COLOR' ? hexToRgba(val.l) : val.l);
  }
}
figma.notify('NUDGE variables created: ' + Object.keys(created).length);
"@
[IO.File]::WriteAllText((Join-Path $here 'apply-variables.figma.js'), $js, $enc)
"Figma Variables: $($counts.variables) variables in $($counts.collections) collections; $($rows.Count) web tokens classified (shared $($stats.shared), mapped $($stats.mapped), not a variable $($stats.notvar), not promoted $($stats.notpromoted), unexpected $($stats.unexpected))."
